/// FitAI Multilingual Localization System
///
/// Supports English plus Pakistan's major regional languages:
/// Urdu, Sindhi, Punjabi, Pashto, Balochi, Hindi and additional
/// regional languages. Each language carries metadata for speech-to-text
/// (STT) and text-to-speech (TTS) locale support so the voice layer can
/// gracefully degrade when a language is not supported on the device.
library;

import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Metadata for a single supported language.
class AppLanguage {
  /// Storage key matching the existing Settings selection (e.g. 'Urdu').
  final String name;

  /// Name written in the language's own script.
  final String nativeName;

  /// BCP-47 locale used for speech-to-text, or null if not reliably supported.
  final String? sttLocale;

  /// BCP-47 locale used for text-to-speech, or null if not reliably supported.
  final String? ttsLocale;

  /// Whether the language is right-to-left.
  final bool isRtl;

  const AppLanguage({
    required this.name,
    required this.nativeName,
    this.sttLocale,
    this.ttsLocale,
    this.isRtl = false,
  });

  bool get supportsStt => sttLocale != null;
  bool get supportsTts => ttsLocale != null;
}

/// Catalogue of every supported language.
class AppLanguages {
  const AppLanguages._();

  static const all = <AppLanguage>[
    AppLanguage(
      name: 'English',
      nativeName: 'English',
      sttLocale: 'en-US',
      ttsLocale: 'en-US',
    ),
    AppLanguage(
      name: 'Urdu',
      nativeName: 'اردو',
      sttLocale: 'ur-PK',
      ttsLocale: 'ur-PK',
      isRtl: true,
    ),
    AppLanguage(
      name: 'Hindi',
      nativeName: 'हिन्दी',
      sttLocale: 'hi-IN',
      ttsLocale: 'hi-IN',
    ),
    AppLanguage(
      name: 'Punjabi',
      nativeName: 'پنجابی',
      sttLocale: 'pa-Guru-IN',
      ttsLocale: 'pa-IN',
      isRtl: true,
    ),
    AppLanguage(
      name: 'Sindhi',
      nativeName: 'سنڌي',
      sttLocale: 'sd-IN',
      ttsLocale: 'sd-IN',
      isRtl: true,
    ),
    AppLanguage(
      name: 'Pashto',
      nativeName: 'پښتو',
      sttLocale: 'ps-AF',
      ttsLocale: 'ps-AF',
      isRtl: true,
    ),
    AppLanguage(
      name: 'Balochi',
      nativeName: 'بلوچی',
      // STT/TTS not reliably available on most devices for Balochi.
      sttLocale: null,
      ttsLocale: null,
      isRtl: true,
    ),
    AppLanguage(
      name: 'Roman English',
      nativeName: 'Roman English',
      sttLocale: 'en-IN',
      ttsLocale: 'en-IN',
      isRtl: false,
    ),
    // Additional regional languages (text + chat only where possible).
    AppLanguage(name: 'Saraiki', nativeName: 'سرائیکی', isRtl: true),
    AppLanguage(name: 'Hindko', nativeName: 'ہندکو', isRtl: true),
    AppLanguage(name: 'Kashmiri', nativeName: 'کٲشُر', isRtl: true),
  ];

  /// Map from language [name] to its Urdu display name, used when the
  /// active app language is any non-English locale.
  static const urduNames = <String, String>{
    'English': 'انگریزی',
    'Urdu': 'اردو',
    'Hindi': 'ہندی',
    'Punjabi': 'پنجابی',
    'Sindhi': 'سندھی',
    'Pashto': 'پشتو',
    'Balochi': 'بلوچی',
    'Roman English': 'رومن انگریزی',
    'Saraiki': 'سرائیکی',
    'Hindko': 'ہندکو',
    'Kashmiri': 'کشمیری',
  };

  static AppLanguage byCode(String? name) {
    if (name == null) return all.first;
    for (final lang in all) {
      if (lang.name == name) return lang;
    }
    return all.first;
  }
}

/// Lightweight string-translation helper. Looks up a key for the active
/// language, falling back to English then to the raw key.
class L {
  L._();

  static String _current = 'English';

  static String get current => _current;

  static AppLanguage get language => AppLanguages.byCode(_current);

  static bool get isRtl => language.isRtl;

  static Future<void> load() async {
    final prefs = await SharedPreferences.getInstance();
    _current = prefs.getString('language') ?? 'English';
  }

  static Future<void> set(String name) async {
    _current = name;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('language', name);
  }

  /// Translate a UI string key.
  static String t(String key) {
    final translations = _strings[key];
    if (translations == null) return key;
    return translations[_current] ?? translations['English'] ?? key;
  }

  /// Directionality-aware builder for the whole app.
  static TextDirection get textDirection =>
      isRtl ? TextDirection.rtl : TextDirection.ltr;
}

